contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        bool reverted; try c.withdrawAll(address(this)) { reverted = false; } catch { reverted = true; }
        // Rule: the withdrawal call succeeds precisely when this contract is the owner.
        // On P: revert iff msg.sender (address(this)) != owner.
        // On M: always reverts, breaking the rule when this contract is the owner.
        assert(reverted == (c.owner() != address(this)));
    }
    receive() external payable {}
}

