contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint amount) public payable {
        require(msg.sender == c.owner(), "must be owner");
        require(address(this).balance >= amount, "insufficient test balance");
        // fund c through its payable fallback using a low-level call
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded, "funding failed");
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        // Rule: a successful withdrawAll transfers out everything,
        // so unless it reverted, c's balance must be zero.
        assert(reverted || (amount == 0 && beforeBalance == 0) || address(c).balance == 0);
    }
    receive() external payable {}
}

